import{_ as e,o as t,c as a,ae as o}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-08-04","description":"","frontmatter":{"date":"2026-08-04T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-08-04-uxtrend.md","filePath":"daily/2026-08-04-uxtrend.md"}'),n={name:"daily/2026-08-04-uxtrend.md"};function s(i,r,g,p,d,l){return t(),a("div",null,[...r[0]||(r[0]=[o('<h1 id="设计趋势-2026-08-04" tabindex="-1">设计趋势 - 2026-08-04 <a class="header-anchor" href="#设计趋势-2026-08-04" aria-label="Permalink to &quot;设计趋势 - 2026-08-04&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势资讯汇总：智能代理用户体验设计成为焦点，强调数字设备上的新型体验；AI驱动工作流程和AI工作流设计规则被讨论，突出功能导向而非模拟人类。最值得关注的是AI辅助工作流开发的最佳实践，以及人工智能时代下的Agent UX设计，后者强调人、算法和系统间的逻辑、沟通和信任。</p><hr><h3 id="_1-面向智能代理的用户体验设计" tabindex="-1">1. 面向智能代理的用户体验设计 <a class="header-anchor" href="#_1-面向智能代理的用户体验设计" aria-label="Permalink to &quot;1. 面向智能代理的用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 设计原则助力数字设备上的新型用户体验</p><p><strong>能解决什么问题</strong>: 如何设计融入日常生活的AI代理系统</p><p><strong>产品应用</strong>: 适用于产品开发，以人为中心，加速智能系统开发</p><p><strong>示例场景</strong>: 智能助手协助用户进行日常任务规划</p><hr><h3 id="_2-ai驱动的工作流程是什么" tabindex="-1">2. AI驱动的工作流程是什么？ <a class="header-anchor" href="#_2-ai驱动的工作流程是什么" aria-label="Permalink to &quot;2. AI驱动的工作流程是什么？&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxtbe.medium.com/ai-workflows-its-not-about-going-faster-it-s-about-thinking-differently-0972defead9c" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI工作流程是人与自动化模型协作的序列。</p><p><strong>能解决什么问题</strong>: 如何将AI融入设计流程而不牺牲用户体验。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI辅助决策和任务执行。</p><p><strong>示例场景</strong>: 设计师提出需求，AI生成信息架构和视觉变体。</p><hr><h3 id="_3-ai工作流设计规则" tabindex="-1">3. AI工作流设计规则 <a class="header-anchor" href="#_3-ai工作流设计规则" aria-label="Permalink to &quot;3. AI工作流设计规则&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://skooloflife.medium.com/the-biggest-mistake-in-ai-workflow-design-mimicking-human-process-instead-of-optimizing-function-628bfa37aa02" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI工作流设计应基于功能而非模拟人类角色。</p><p><strong>能解决什么问题</strong>: AI系统因错误地模拟人类角色而设计失败。</p><p><strong>产品应用</strong>: 适用于任何需要AI自动化流程的实际产品。</p><p><strong>示例场景</strong>: 自动化客户服务系统中的智能问答功能。</p><hr><h3 id="_4-ai辅助工作流开发的最佳实践" tabindex="-1">4. AI辅助工作流开发的最佳实践 <a class="header-anchor" href="#_4-ai辅助工作流开发的最佳实践" aria-label="Permalink to &quot;4. AI辅助工作流开发的最佳实践&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@sai.kancherla/best-practices-for-ai-assisted-workflow-development-29096fa94d7b" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 遵循最佳实践以确保AI辅助工作流的效率和可靠性。</p><p><strong>能解决什么问题</strong>: 解决复杂工作流开发中的效率和准确性问题。</p><p><strong>产品应用</strong>: 可以应用于软件开发，通过AI加速编码并处理常规任务。</p><p><strong>示例场景</strong>: 开发人员利用AI构建自动化客户服务流程。</p><hr><h3 id="_5-人工智能时代的用户体验设计-agent-ux" tabindex="-1">5. 人工智能时代的用户体验设计：Agent UX <a class="header-anchor" href="#_5-人工智能时代的用户体验设计-agent-ux" aria-label="Permalink to &quot;5. 人工智能时代的用户体验设计：Agent UX&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@purvashobhit/ux-2-0-agent-experience-experience-design-in-the-age-of-ai-agents-a32230569449" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: Agent UX强调在人、算法和系统间的逻辑、沟通和信任。</p><p><strong>能解决什么问题</strong>: 解决非人类用户（如AI代理）的体验设计问题。</p><p><strong>产品应用</strong>: 适用于需要AI代理与人类协同工作的产品和服务。</p><p><strong>示例场景</strong>: AI代理代替用户预约医生会面。</p><hr><h3 id="_6-figma-2026年设计师现状-ai提升设计质量" tabindex="-1">6. Figma 2026年设计师现状：AI提升设计质量 <a class="header-anchor" href="#_6-figma-2026年设计师现状-ai提升设计质量" aria-label="Permalink to &quot;6. Figma 2026年设计师现状：AI提升设计质量&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/product-designers-are-not-being-replaced-they-are-being-sorted-6e2fb0492ed2" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI在设计领域的应用提升了质量而非仅速度。</p><p><strong>能解决什么问题</strong>: 设计师如何利用AI提升设计质量并适应新技能需求。</p><p><strong>产品应用</strong>: 应用于产品设计，通过AI工具提升视觉和策略性设计。</p><p><strong>示例场景</strong>: 设计师使用Figma和Claude进行代码与设计的双向转换。</p><hr><h3 id="_7-ai代理应用的ux设计实用指南" tabindex="-1">7. AI代理应用的UX设计实用指南 <a class="header-anchor" href="#_7-ai代理应用的ux设计实用指南" aria-label="Permalink to &quot;7. AI代理应用的UX设计实用指南&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@amarpreetbhatia/ux-design-for-ai-agent-applications-a-practical-guide-ce41a6d545ab" target="_blank" rel="noreferrer">UX Design for AI Agent Applications: A Practical Guide | by Amarpreet Bhatia | Medium</a></p><p><strong>一句话摘要</strong>: 设计AI代理应用时，需确保其可见性、可控性、可解释性、可靠性、可恢复性和可学习性。</p><p><strong>能解决什么问题</strong>: 提升用户体验，使AI代理更易于理解和帮助用户。</p><p><strong>产品应用</strong>: 适用于任何需要AI代理的产品设计，通过遵循最佳实践，提高用户满意度。</p><p><strong>示例场景</strong>: 客户支持AI代理，每一步都显示操作进度并要求用户在关键决策点输入。</p><hr><h3 id="_8-ai代理工作流设计模式概览" tabindex="-1">8. AI代理工作流设计模式概览 <a class="header-anchor" href="#_8-ai代理工作流设计模式概览" aria-label="Permalink to &quot;8. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，分类并举例说明。</p><p><strong>能解决什么问题</strong>: 如何设计能模拟人类推理的AI代理工作流。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，作为任务协调器处理不同问题。</p><p><strong>示例场景</strong>: 开发基于这些原则的AI代理，灵活处理各种任务。</p><hr><h3 id="_9-构建由claude-code驱动的ai工作流" tabindex="-1">9. 构建由Claude Code驱动的AI工作流 <a class="header-anchor" href="#_9-构建由claude-code驱动的ai工作流" aria-label="Permalink to &quot;9. 构建由Claude Code驱动的AI工作流&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/designing-with-claude-code-and-codex-cli-building-ai-driven-workflows-powered-by-code-connect-ui-f10c136ec11f" target="_blank" rel="noreferrer">Building AI-driven workflows powered by Claude Code and ...</a></p><p><strong>一句话摘要</strong>: AI与现有基础设施集成，提升设计系统价值</p><p><strong>能解决什么问题</strong>: 如何将AI技术与设计和开发工作流程有效结合</p><p><strong>产品应用</strong>: 适用于大型团队，通过AI与设计系统整合，提高代码和原型的可维护性</p><p><strong>示例场景</strong>: 使用Figma变量映射CSS，实现设计与代码的无缝对接</p><hr><h3 id="_10-代理型用户体验-7个原则设计智能代理系统" tabindex="-1">10. 代理型用户体验：7个原则设计智能代理系统 <a class="header-anchor" href="#_10-代理型用户体验-7个原则设计智能代理系统" aria-label="Permalink to &quot;10. 代理型用户体验：7个原则设计智能代理系统&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/agentic-ux-7-principles-for-designing-systems-with-agents-019512c2caa9" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 设计系统让智能代理在后台有效加速人类工作</p><p><strong>能解决什么问题</strong>: 如何构建系统以支持智能代理更好地执行任务</p><p><strong>产品应用</strong>: 适用于需要自动化和智能决策的产品，如智能助手</p><p><strong>示例场景</strong>: 智能助手自动完成日程安排和邮件分类</p><hr>',75)])])}const u=e(n,[["render",s]]);export{c as __pageData,u as default};
